// The planner feature's PUBLIC API — domain only (`delete-the-planner-ui-keep-the-planner`).
//
// This barrel used to export the ProjectsWorkspace and mount the whole planner screen. That screen is
// gone: planning is the director's job now — the architect runs discovery with the user, then creates a
// director that completes the plan and designs its team. What is NOT gone is the planner's domain, and
// this file is the boundary that keeps it reachable.
//
// EVERY EXPORT HERE IS REACT-FREE, and that is the invariant worth stating: eleven modules outside this
// feature import through this barrel (#1545 lets them reach nothing else), so a UI export creeping back
// in would pull React into the store's type graph and into Glance. The rule is mechanical — if it
// imports react, it does not belong here.
//
// The functions the screen used to drive are all reachable headlessly now: `bsc plan` for the plan,
// `bsc publish` for the GitHub structure, `bsc fleet start` for the fleet.

// The canonical file shape the tunnel reads for its payload parity harness.
export type { CanonicalFile } from "@/features/planner/lib/plannerCore";
// The `plan` store_state builder (#3760) — the plan domain is planner-published, not projected by
// useStoreProjector, so the tunnel harness reaches it here like every other domain.
export { buildPlanBoardPayload, type PlanBoardPayload } from "@/features/planner/session/planBoardProjection";
// Gist install/publish — extension bundles, shared with the studio + designs share flows.
export {
  validateManifest, wrapExtension, encodeShareCode, decodeShareCode,
  type ExtensionManifest, type ValidateResult,
} from "@/features/planner/lib/gist/manifest";
export { installFromGist, publishGist } from "@/features/planner/lib/gist/gist";
// The project APPLICATION ARCHITECTURE (#3802/#3786) — Glance surfaces it on each project node, and
// reaches the TYPE through the barrel rather than the deep `lib/classifyConfig` path.
export type { AppType } from "@/features/planner/lib/classifyConfig";
// Fleet flow rules — the console launch reads them to scope a worker's git/gh permissions.
export { flowPermissionRules, flowGrantedPushCommands } from "@/features/planner/fleet/flowPermissions";
// The durable projects-DB bridge (#2995/#3966) — the app shell's boot migration and Glance's project
// list both go through here, not through the persisted draft cache.
export { addDbProject, setDbTriaged } from "@/features/planner/list/projectsDbBridge";
export { listDbProjects, type DbProject } from "@/features/planner/list/projectsDbBridge";
// Director drive — the app's director pump reads these to decide when to nudge a stalled fleet.
export {
  resolveDirectorDrive, askKey,
  requestKey,
  shouldRemind,
  ASK_REMINDER_MS, DEFAULT_HEARTBEAT_MS, INJECT_COOLDOWN_MS,
} from "@/features/planner/fleet/directorDrive";
